-- 2026-11-15 每日收录：糖果盒子 2、多边形寓言、Trimps，均为 embed（站内打开原作）。
-- 只插入，不改已有行；INSERT OR IGNORE 防止与本地 jiwan.sql 重复。

INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('candy-box-2', '糖果盒子 2', 'Candy Box 2', 'tangguohezi tangguo candy box 2 candybox', 'aniwey', '', '', NULL, '', 0, 2013, 'idle', '["放置","文字冒险","ASCII"]', 330, 0.06, 'clicker', 'https://candybox2.github.io/', 0, 0, 0, 1, 0, 0, 1, 'long', 'hosted', '先攒糖果，再去打一条龙', '从「你有 0 颗糖果」开始，用 ASCII 画出来的放置冒险，越玩地图越大。', 'An ASCII idle adventure that starts with “You have 0 candies” and keeps opening up.', '由 aniwey 制作，JavaScript 源码以 GPL-3.0 发布。原页托管在 candybox2.github.io，不是即玩的作品。在即玩里直接打开原作。存档保存在浏览器本地，开玩不用登录。', 'Made by aniwey; the JavaScript source is released under GPL-3.0. Hosted at candybox2.github.io; it is not a Jiwan original. It opens here. Saves stay in your browser; no account needed.', 'assets/posters/candy-box-2.jpg', 1280, 800, 'center', '["assets/posters/candy-box-2.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -13, 1794708000000, 'Save up candies, then go fight a dragon.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('parable-of-polygons', '多边形寓言', 'Parable of the Polygons', 'duobianxing yuyan duobianxingyuyan polygons parable', 'Vi Hart, Nicky Case', '', '', NULL, '', 0, 2014, 'story', '["互动叙事","科普","模拟"]', 220, 0.08, 'story', 'https://ncase.me/polygons/', 0, 0, 0, 1, 0, 0, 1, 'short', 'hosted', '一点点偏好，怎么拼成一道墙', '拖动三角形和正方形，看个人的小偏好怎样变成整体的隔离。原页有中文版入口。', 'Drag triangles and squares to see how small personal biases add up to segregation.', '由 Vi Hart 和 Nicky Case 制作，以 CC0 1.0 贡献到公共领域。原页托管在 ncase.me/polygons，不是即玩的作品。在即玩里直接打开原作。页首可切换中文等多种语言。', 'Made by Vi Hart and Nicky Case and released under CC0 1.0. Hosted at ncase.me/polygons; it is not a Jiwan original. It opens here. Translations, including Chinese, are linked at the top of the page.', 'assets/posters/parable-of-polygons.jpg', 1280, 800, 'center', '["assets/posters/parable-of-polygons.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -12, 1794708000000, 'How a little bias builds a wall.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('trimps', 'Trimps', 'Trimps', 'trimps fangzhi shuxue', 'Greensatellite', '', '', NULL, '', 0, 2015, 'idle', '["放置","策略","增量"]', 140, 0.08, 'clicker', 'https://trimps.github.io/', 0, 0, 0, 1, 0, 0, 1, 'long', 'hosted', '从采食物开始，带一群小怪物往前推', '采集、建造、繁殖小怪物，再一张张地图往前打的重度增量放置游戏。', 'A deep incremental game: gather, build, breed Trimps and push through map after map.', '由 Greensatellite 制作，源码以 GPL-2.0 在 GitHub 发布。原页托管在 trimps.github.io，不是即玩的作品。在即玩里直接打开原作。存档默认保存在浏览器本地，开场弹窗里的「在线存档」可选，选「Don’t Enable」即可不登录开玩。', 'Made by Greensatellite; the source is GPL-2.0 on GitHub. Hosted at trimps.github.io; it is not a Jiwan original. It opens here. Saves are local by default; online saving in the welcome dialog is optional.', 'assets/posters/trimps.jpg', 1280, 800, 'center', '["assets/posters/trimps.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -11, 1794708000000, 'Start with food, then march a horde forward.', '', '', 1);
